() => {
  const v = id => (document.getElementById(id) || {}).value ?? null;
  const t = s => { const e = document.querySelector(s); return e ? e.innerText.trim().replace(/\s+/g, ' ') : null; };
  const lbl = i => { const l = document.querySelector('label[for="' + i.id + '"]'); return l ? l.innerText.trim() : i.value; };
  return {first: v('firstName'), last: v('lastName'), email: v('userEmail'),
    gender: [...document.querySelectorAll('input[name=gender]:checked')].map(lbl), mobile: v('userNumber'), dob: v('dateOfBirthInput'),
    subjects: [...document.querySelectorAll('#subjectsContainer [class*=multiValue]')].map(e => e.innerText.trim()),
    hobbies: [...document.querySelectorAll('#hobbiesWrapper input:checked')].map(lbl), address: v('currentAddress'),
    state: t('#state [class*=singleValue]'), city: t('#city [class*=singleValue]')};
}

() => {
  const q = n => document.querySelector('[name=' + n + ']');
  const sel = q('my-select');
  return {text: q('my-text').value, textarea: q('my-textarea').value, select: sel.options[sel.selectedIndex].text,
    datalist: q('my-datalist').value, color: q('my-colors').value, date: q('my-date').value, range: q('my-range').value};
}
